-- ============================================================================
-- NusaSuite — Skema PostgreSQL (dihasilkan dari data/app.db)
-- Dibuat oleh: node scripts/buat-skema-pg.mjs  (boleh dijalankan ulang)
-- Jumlah tabel: 72
--
-- Konvensi konversi dari SQLite:
--   * INTEGER PRIMARY KEY AUTOINCREMENT -> BIGINT GENERATED BY DEFAULT
--     AS IDENTITY PRIMARY KEY (BY DEFAULT agar import id lama tetap bisa)
--   * INTEGER lain -> BIGINT (wajib: tipe FK harus sama dengan PK yang diacu)
--   * REAL (harga/qty/total) -> NUMERIC(19,4) (uang presisi, tanpa float error)
--   * flag 0/1 (aktif/pakai/bawaan/periode_aktif + CHECK IN (0,1)) -> BOOLEAN
--   * TEXT DEFAULT strftime(datetime) -> TIMESTAMPTZ DEFAULT now()
--   * TEXT DEFAULT date()/strftime(date) -> DATE DEFAULT CURRENT_DATE
--   * kolom JSON teks (data_json, params_json, blok, teks struk, ...) -> JSONB
--   * settings.nilai SENGAJA tetap TEXT (campuran string biasa + array JSON)
--   * COLLATE NOCASE dibuang -> gunakan ILIKE / CITEXT di query (lihat db.pg.ts)
--   * Trigger ADA di 002_pemicu_pg.sql (ditulis tangan, bukan hasil generator)
-- ============================================================================

CREATE EXTENSION IF NOT EXISTS citext;

CREATE TABLE accounts (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  kode TEXT NOT NULL,
  nama TEXT NOT NULL,
  tipe TEXT NOT NULL,
  induk_id BIGINT,
  saldo_normal TEXT NOT NULL DEFAULT 'debit' CHECK (saldo_normal IN ('debit', 'kredit')),
  aktif BOOLEAN NOT NULL DEFAULT TRUE,
  dibuat_oleh BIGINT,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  diubah_pada TIMESTAMPTZ,
  UNIQUE (kode)
);

CREATE TABLE alias_barang (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  teks TEXT NOT NULL,
  product_id BIGINT,
  grup TEXT,
  supplier_id BIGINT,
  pakai BOOLEAN NOT NULL DEFAULT TRUE,
  terakhir_pakai TIMESTAMPTZ NOT NULL DEFAULT now(),
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (teks)
);

CREATE TABLE annual_processes (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  no_proses TEXT NOT NULL,
  gudang_id BIGINT,
  sampai DATE NOT NULL,
  periode_baru_dari DATE NOT NULL,
  user_id BIGINT,
  jumlah_hapus JSONB NOT NULL DEFAULT '{}'::jsonb,
  pratinjau JSONB NOT NULL DEFAULT '{}'::jsonb,
  dipulihkan_pada TIMESTAMPTZ,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (no_proses)
);

CREATE TABLE audit_logs (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT,
  waktu TIMESTAMPTZ NOT NULL DEFAULT now(),
  aksi TEXT NOT NULL,
  tabel TEXT NOT NULL,
  record_id TEXT,
  data_sebelum TEXT,
  data_sesudah TEXT,
  alasan TEXT
);

CREATE TABLE brands (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nama TEXT NOT NULL,
  dibuat_oleh BIGINT,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  diubah_pada TIMESTAMPTZ,
  size_profile_id BIGINT,
  UNIQUE (nama)
);

CREATE TABLE cash_accounts (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  kode TEXT NOT NULL,
  nama TEXT NOT NULL,
  jenis TEXT NOT NULL DEFAULT 'kas' CHECK (jenis IN ('kas', 'bank', 'e-wallet')),
  saldo_awal NUMERIC(19,4) NOT NULL DEFAULT 0,
  aktif BOOLEAN NOT NULL DEFAULT TRUE,
  dibuat_oleh BIGINT,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  diubah_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (kode)
);

CREATE TABLE cash_transactions (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tipe TEXT NOT NULL CHECK (tipe IN ('masuk', 'keluar', 'transfer')),
  tanggal DATE NOT NULL DEFAULT CURRENT_DATE,
  nomor TEXT NOT NULL,
  cash_account_id BIGINT NOT NULL,
  cash_account_tujuan_id BIGINT,
  category_id BIGINT,
  jumlah NUMERIC(19,4) NOT NULL,
  keterangan TEXT,
  sumber_tipe TEXT,
  sumber_id BIGINT,
  dibuat_oleh BIGINT,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (nomor),
  CHECK (tipe <> 'transfer' OR cash_account_tujuan_id IS NOT NULL)
);

CREATE TABLE cashier_shifts (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL,
  buka_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  tutup_pada TIMESTAMPTZ,
  kas_awal NUMERIC(19,4) NOT NULL DEFAULT 0,
  kas_akhir_sistem NUMERIC(19,4),
  kas_akhir_fisik NUMERIC(19,4),
  selisih NUMERIC(19,4),
  dibuat_oleh BIGINT,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  diubah_pada TIMESTAMPTZ
);

CREATE TABLE categories (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nama TEXT NOT NULL,
  dibuat_oleh BIGINT,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  diubah_pada TIMESTAMPTZ,
  size_profile_id BIGINT,
  UNIQUE (nama)
);

CREATE TABLE chat_match_logs (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tipe TEXT NOT NULL DEFAULT 'produk',
  teks TEXT NOT NULL,
  hasil TEXT NOT NULL,
  skor BIGINT NOT NULL DEFAULT 0,
  product_id BIGINT,
  supplier_id BIGINT,
  pengguna_id BIGINT,
  detail_json JSONB,
  waktu TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE customers (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nama TEXT NOT NULL,
  telepon TEXT,
  alamat TEXT,
  limit_piutang NUMERIC(19,4) NOT NULL DEFAULT 0,
  dibuat_oleh BIGINT,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  diubah_pada TIMESTAMPTZ,
  aktif BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE dashboard_layout (
  user_id BIGINT PRIMARY KEY,
  json JSONB NOT NULL,
  diubah_pada TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE dashboard_layout_peran (
  peran TEXT PRIMARY KEY,
  json JSONB NOT NULL,
  diubah_pada TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE document_counters (
  kunci TEXT PRIMARY KEY,
  terakhir BIGINT NOT NULL DEFAULT 0
);

CREATE TABLE expense_categories (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nama TEXT NOT NULL,
  tipe TEXT NOT NULL CHECK (tipe IN ('pengeluaran', 'pemasukan')),
  aktif BOOLEAN NOT NULL DEFAULT TRUE,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (nama)
);

CREATE TABLE held_sales (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  kasir_id BIGINT NOT NULL,
  data_json JSONB NOT NULL,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE import_batches (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  modul TEXT NOT NULL,
  nama_file TEXT NOT NULL,
  total_baris BIGINT NOT NULL DEFAULT 0,
  baris_valid BIGINT NOT NULL DEFAULT 0,
  baris_error BIGINT NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'diproses' CHECK (status IN ('diproses', 'selesai', 'gagal')),
  user_id BIGINT,
  waktu TIMESTAMPTZ NOT NULL DEFAULT now(),
  undo_data TEXT,
  diurungkan BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE TABLE import_errors (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  batch_id BIGINT NOT NULL,
  nomor_baris BIGINT NOT NULL,
  kolom TEXT,
  pesan TEXT NOT NULL,
  nilai TEXT
);

CREATE TABLE invoice_templates (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nama TEXT NOT NULL,
  jenis TEXT NOT NULL CHECK (jenis IN ('penjualan', 'pembelian', 'surat_jalan')),
  bawaan BOOLEAN NOT NULL DEFAULT FALSE,
  kertas TEXT NOT NULL DEFAULT 'A4',
  orientasi TEXT NOT NULL DEFAULT 'portrait' CHECK (orientasi IN ('portrait', 'landscape')),
  lebar_mm NUMERIC(19,4),
  tinggi_mm NUMERIC(19,4),
  margin_atas NUMERIC(19,4) NOT NULL DEFAULT 12,
  margin_kanan NUMERIC(19,4) NOT NULL DEFAULT 12,
  margin_bawah NUMERIC(19,4) NOT NULL DEFAULT 12,
  margin_kiri NUMERIC(19,4) NOT NULL DEFAULT 12,
  skala NUMERIC(19,4) NOT NULL DEFAULT 100,
  ukuran_font NUMERIC(19,4) NOT NULL DEFAULT 10,
  aksen TEXT NOT NULL DEFAULT '#2563eb',
  blok JSONB NOT NULL DEFAULT '{}'::jsonb,
  urutan_kolom TEXT NOT NULL DEFAULT '["kode", "nama", "qty", "satuan", "harga", "diskon", "subtotal"]',
  teks JSONB NOT NULL DEFAULT '{}'::jsonb,
  dibuat_oleh BIGINT,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  diubah_pada TIMESTAMPTZ,
  pengaturan_kolom TEXT NOT NULL DEFAULT '{}',
  singkat_kolom TEXT NOT NULL DEFAULT 'auto'
);

CREATE TABLE invoices (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  no_faktur TEXT NOT NULL,
  jenis TEXT NOT NULL CHECK (jenis IN ('penjualan', 'pembelian')),
  sumber_tipe TEXT NOT NULL,
  sumber_id BIGINT NOT NULL,
  tanggal TIMESTAMPTZ NOT NULL,
  template_id BIGINT,
  pihak_nama TEXT,
  pihak_telepon TEXT,
  pihak_alamat TEXT,
  subtotal NUMERIC(19,4) NOT NULL DEFAULT 0,
  diskon NUMERIC(19,4) NOT NULL DEFAULT 0,
  pajak_persen NUMERIC(19,4) NOT NULL DEFAULT 0,
  pajak NUMERIC(19,4) NOT NULL DEFAULT 0,
  total NUMERIC(19,4) NOT NULL DEFAULT 0,
  terbilang TEXT,
  catatan TEXT,
  data_json JSONB NOT NULL DEFAULT '{}'::jsonb,
  status TEXT NOT NULL DEFAULT 'terbit' CHECK (status IN ('terbit', 'batal')),
  dibuat_oleh BIGINT,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  diubah_pada TIMESTAMPTZ,
  UNIQUE (no_faktur)
);

CREATE TABLE journal_lines (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  journal_id BIGINT NOT NULL,
  account_id BIGINT NOT NULL,
  product_id BIGINT,
  nama_produk TEXT,
  sku TEXT,
  debit NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK (debit >= 0),
  kredit NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK (kredit >= 0),
  keterangan TEXT,
  CHECK (debit = 0 OR kredit = 0)
);

CREATE TABLE journals (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  no_jurnal TEXT NOT NULL,
  tanggal DATE NOT NULL DEFAULT CURRENT_DATE,
  period_id BIGINT NOT NULL,
  sumber_tipe TEXT NOT NULL,
  sumber_id BIGINT,
  keterangan TEXT,
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'disahkan', 'batal')),
  dibuat_oleh BIGINT,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  diubah_pada TIMESTAMPTZ,
  UNIQUE (no_jurnal)
);

CREATE TABLE locations (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  warehouse_id BIGINT NOT NULL,
  zona TEXT,
  rak TEXT,
  bin TEXT,
  kode_lokasi TEXT NOT NULL,
  dibuat_oleh BIGINT,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  diubah_pada TIMESTAMPTZ,
  UNIQUE (kode_lokasi)
);

CREATE TABLE operator_komposisi (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  label TEXT NOT NULL,
  pengali BIGINT NOT NULL,
  kata_kunci TEXT NOT NULL DEFAULT '[]',
  aktif BOOLEAN NOT NULL DEFAULT TRUE,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  diubah_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (label)
);

CREATE TABLE opname_items (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  session_id BIGINT NOT NULL,
  product_id BIGINT NOT NULL,
  location_id BIGINT,
  qty_sistem NUMERIC(19,4) NOT NULL DEFAULT 0,
  qty_fisik NUMERIC(19,4) NOT NULL DEFAULT 0,
  selisih NUMERIC(19,4) NOT NULL DEFAULT 0,
  catatan TEXT,
  dihitung_manual BOOLEAN NOT NULL DEFAULT FALSE,
  jml_scan BIGINT NOT NULL DEFAULT 0,
  sumber TEXT,
  dihitung_pada TIMESTAMPTZ
);

CREATE TABLE opname_scans (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  session_id BIGINT NOT NULL,
  barcode TEXT NOT NULL,
  product_id BIGINT,
  location_id BIGINT,
  waktu TIMESTAMPTZ NOT NULL DEFAULT now(),
  user_id BIGINT,
  dibatalkan BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE TABLE opname_sessions (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  no_dokumen TEXT NOT NULL,
  warehouse_id BIGINT NOT NULL,
  location_id BIGINT,
  tanggal TIMESTAMPTZ NOT NULL DEFAULT now(),
  metode TEXT NOT NULL DEFAULT 'manual' CHECK (metode IN ('manual', 'scan', 'gabungan')),
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'disahkan', 'batal')),
  penanggung_jawab_id BIGINT NOT NULL,
  disetujui_oleh BIGINT,
  dibuat_oleh BIGINT,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  diubah_pada TIMESTAMPTZ,
  tahap TEXT NOT NULL DEFAULT 'hitung' CHECK (tahap IN ('hitung', 'tinjau')),
  selesai_hitung_pada TIMESTAMPTZ,
  disetujui_pada TIMESTAMPTZ,
  catatan TEXT,
  impor_file_nama TEXT,
  impor_file_data BYTEA,
  impor_baris BIGINT NOT NULL DEFAULT 0,
  impor_pada TIMESTAMPTZ,
  UNIQUE (no_dokumen)
);

CREATE TABLE pack_items (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  pack_id BIGINT NOT NULL,
  product_id BIGINT NOT NULL,
  qty NUMERIC(19,4) NOT NULL CHECK (qty > 0),
  UNIQUE (pack_id, product_id)
);

CREATE TABLE packs (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  kode_box TEXT NOT NULL,
  barcode_box TEXT,
  nama TEXT NOT NULL,
  dibuat_oleh BIGINT,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  diubah_pada TIMESTAMPTZ,
  UNIQUE (kode_box),
  UNIQUE (barcode_box)
);

CREATE TABLE password_resets (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL,
  token_hash TEXT NOT NULL,
  kanal TEXT NOT NULL,
  tujuan TEXT,
  kedaluwarsa TEXT NOT NULL,
  dipakai_pada TIMESTAMPTZ,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE payables (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  purchase_id BIGINT NOT NULL,
  supplier_id BIGINT NOT NULL,
  jatuh_tempo DATE,
  total NUMERIC(19,4) NOT NULL DEFAULT 0,
  terbayar NUMERIC(19,4) NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'belum' CHECK (status IN ('belum', 'sebagian', 'lunas', 'batal')),
  dibuat_oleh BIGINT,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  diubah_pada TIMESTAMPTZ,
  UNIQUE (purchase_id)
);

CREATE TABLE payment_method_accounts (
  metode TEXT PRIMARY KEY,
  cash_account_id BIGINT NOT NULL
);

CREATE TABLE payments (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tipe TEXT NOT NULL,
  referensi_id BIGINT,
  tanggal DATE NOT NULL DEFAULT CURRENT_DATE,
  jumlah NUMERIC(19,4) NOT NULL,
  akun_kas_id BIGINT NOT NULL,
  dibuat_oleh BIGINT,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  diubah_pada TIMESTAMPTZ
);

CREATE TABLE pengaturan_dashboard (
  user_id BIGINT NOT NULL,
  kartu_id TEXT NOT NULL,
  tampil BOOLEAN NOT NULL DEFAULT TRUE,
  diubah_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, kartu_id)
);

CREATE TABLE pengaturan_dashboard_peran (
  peran TEXT NOT NULL,
  kartu_id TEXT NOT NULL,
  tampil BOOLEAN NOT NULL DEFAULT TRUE,
  diubah_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (peran, kartu_id)
);

CREATE TABLE periods (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tahun BIGINT NOT NULL,
  bulan BIGINT NOT NULL CHECK (bulan BETWEEN 1 AND 12),
  status TEXT NOT NULL DEFAULT 'buka' CHECK (status IN ('buka', 'tutup')),
  UNIQUE (tahun, bulan)
);

CREATE TABLE pesan_keluar (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  jenis TEXT NOT NULL,
  tujuan TEXT NOT NULL,
  isi TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'antre',
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE products (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nama TEXT NOT NULL,
  sku TEXT NOT NULL,
  barcode TEXT,
  category_id BIGINT,
  brand_id BIGINT,
  satuan_dasar_id BIGINT,
  harga_beli NUMERIC(19,4) NOT NULL DEFAULT 0,
  harga_jual NUMERIC(19,4) NOT NULL DEFAULT 0,
  stok_min NUMERIC(19,4) NOT NULL DEFAULT 0,
  aktif BOOLEAN NOT NULL DEFAULT TRUE,
  dibuat_oleh BIGINT,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  diubah_pada TIMESTAMPTZ,
  kode_item TEXT,
  foto_url TEXT,
  deleted_at TIMESTAMPTZ,
  deskripsi TEXT,
  size_profile_id BIGINT,
  UNIQUE (sku),
  UNIQUE (barcode)
);

CREATE TABLE purchase_chat_logs (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  purchase_id BIGINT,
  chat_sesi TEXT,
  pesan_user TEXT NOT NULL,
  pesan_bot TEXT,
  hasil_parse_json JSONB,
  waktu TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE purchase_items (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  purchase_id BIGINT NOT NULL,
  product_id BIGINT NOT NULL,
  nama_produk TEXT NOT NULL,
  sku TEXT NOT NULL,
  qty NUMERIC(19,4) NOT NULL CHECK (qty > 0),
  unit_id BIGINT,
  harga_beli NUMERIC(19,4) NOT NULL DEFAULT 0,
  diskon NUMERIC(19,4) NOT NULL DEFAULT 0,
  subtotal NUMERIC(19,4) NOT NULL DEFAULT 0,
  pack_id BIGINT,
  sumber_scan TEXT,
  direvisi BOOLEAN NOT NULL DEFAULT FALSE,
  location_id BIGINT
);

CREATE TABLE purchase_scan_logs (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  purchase_id BIGINT NOT NULL,
  barcode TEXT NOT NULL,
  tipe TEXT NOT NULL CHECK (tipe IN ('box', 'satuan', 'tidak_dikenal')),
  pack_id BIGINT,
  product_id BIGINT,
  waktu TIMESTAMPTZ NOT NULL DEFAULT now(),
  user_id BIGINT
);

CREATE TABLE purchases (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  no_dokumen TEXT NOT NULL,
  no_po TEXT,
  no_grn TEXT,
  no_faktur TEXT,
  tanggal TIMESTAMPTZ NOT NULL DEFAULT now(),
  supplier_id BIGINT NOT NULL,
  warehouse_id BIGINT NOT NULL,
  metode_input TEXT NOT NULL DEFAULT 'biasa' CHECK (metode_input IN ('biasa', 'scan', 'chatbot')),
  subtotal NUMERIC(19,4) NOT NULL DEFAULT 0,
  diskon NUMERIC(19,4) NOT NULL DEFAULT 0,
  pajak_persen NUMERIC(19,4) NOT NULL DEFAULT 0,
  pajak NUMERIC(19,4) NOT NULL DEFAULT 0,
  total NUMERIC(19,4) NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'diterima', 'disahkan', 'batal')),
  diterima_pada TIMESTAMPTZ,
  disahkan_pada TIMESTAMPTZ,
  dibuat_oleh BIGINT,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  diubah_pada TIMESTAMPTZ,
  chat_rincian_json JSONB,
  UNIQUE (no_dokumen)
);

CREATE TABLE receivables (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  sale_id BIGINT NOT NULL,
  customer_id BIGINT NOT NULL,
  jatuh_tempo DATE,
  total NUMERIC(19,4) NOT NULL DEFAULT 0,
  terbayar NUMERIC(19,4) NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'belum' CHECK (status IN ('belum', 'sebagian', 'lunas', 'batal')),
  dibuat_oleh BIGINT,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  diubah_pada TIMESTAMPTZ,
  UNIQUE (sale_id)
);

CREATE TABLE recovery_codes (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL,
  kode_hash TEXT NOT NULL,
  dipakai_pada TIMESTAMPTZ,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE report_files (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  saved_report_id BIGINT,
  laporan TEXT NOT NULL,
  nama TEXT NOT NULL,
  periode_dari DATE,
  periode_sampai DATE,
  params_json JSONB NOT NULL DEFAULT '{}'::jsonb,
  ringkas_json JSONB,
  dibuat_oleh BIGINT,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE role_hak_khusus (
  role_id BIGINT PRIMARY KEY,
  lihat_hpp BOOLEAN NOT NULL DEFAULT TRUE,
  ubah_harga_kasir BOOLEAN NOT NULL DEFAULT TRUE,
  diskon_maks NUMERIC(19,4) NOT NULL DEFAULT 100,
  hapus_transaksi BOOLEAN NOT NULL DEFAULT TRUE,
  proses_tahunan BOOLEAN NOT NULL DEFAULT FALSE,
  void_retur BOOLEAN NOT NULL DEFAULT FALSE,
  buka_tutup_shift BOOLEAN NOT NULL DEFAULT FALSE,
  lihat_laba BOOLEAN NOT NULL DEFAULT FALSE,
  ubah_stok_manual BOOLEAN NOT NULL DEFAULT FALSE,
  sahkan_opname BOOLEAN NOT NULL DEFAULT FALSE,
  hapus_massal BOOLEAN NOT NULL DEFAULT FALSE,
  kelola_pengguna BOOLEAN NOT NULL DEFAULT FALSE,
  ubah_pengaturan BOOLEAN NOT NULL DEFAULT FALSE,
  akses_semua_toko BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE TABLE role_permissions (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  role_id BIGINT NOT NULL,
  menu TEXT NOT NULL,
  aksi TEXT NOT NULL CHECK (aksi IN ('lihat','tambah','ubah','hapus','sahkan','impor','ekspor','cetak')),
  UNIQUE (role_id, menu, aksi)
);

CREATE TABLE roles (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nama TEXT NOT NULL,
  cakupan_toko TEXT,
  bawaan BOOLEAN NOT NULL DEFAULT FALSE,
  menu_awal TEXT,
  UNIQUE (nama)
);

CREATE TABLE sale_items (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  sale_id BIGINT NOT NULL,
  product_id BIGINT NOT NULL,
  nama_produk TEXT NOT NULL,
  sku TEXT NOT NULL,
  qty NUMERIC(19,4) NOT NULL CHECK (qty > 0),
  unit_id BIGINT,
  harga NUMERIC(19,4) NOT NULL DEFAULT 0,
  diskon NUMERIC(19,4) NOT NULL DEFAULT 0,
  subtotal NUMERIC(19,4) NOT NULL DEFAULT 0,
  hpp NUMERIC(19,4) NOT NULL DEFAULT 0,
  UNIQUE (sale_id, product_id)
);

CREATE TABLE sale_payments (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  sale_id BIGINT NOT NULL,
  metode TEXT NOT NULL,
  jumlah NUMERIC(19,4) NOT NULL,
  referensi TEXT
);

CREATE TABLE sale_return_items (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  return_id BIGINT NOT NULL,
  product_id BIGINT NOT NULL,
  nama_produk TEXT NOT NULL,
  sku TEXT NOT NULL,
  qty NUMERIC(19,4) NOT NULL CHECK (qty > 0),
  harga NUMERIC(19,4) NOT NULL DEFAULT 0,
  UNIQUE (return_id, product_id)
);

CREATE TABLE sale_returns (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  no_dokumen TEXT NOT NULL,
  sale_id BIGINT NOT NULL,
  tanggal TIMESTAMPTZ NOT NULL DEFAULT now(),
  alasan TEXT,
  total NUMERIC(19,4) NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'disahkan', 'batal')),
  dibuat_oleh BIGINT,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  diubah_pada TIMESTAMPTZ,
  UNIQUE (no_dokumen)
);

CREATE TABLE sales (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  no_dokumen TEXT NOT NULL,
  tanggal TIMESTAMPTZ NOT NULL DEFAULT now(),
  shift_id BIGINT,
  kasir_id BIGINT NOT NULL,
  customer_id BIGINT,
  warehouse_id BIGINT NOT NULL,
  mode_pos TEXT NOT NULL DEFAULT 'foto' CHECK (mode_pos IN ('foto', 'cepat')),
  subtotal NUMERIC(19,4) NOT NULL DEFAULT 0,
  diskon NUMERIC(19,4) NOT NULL DEFAULT 0,
  pajak NUMERIC(19,4) NOT NULL DEFAULT 0,
  total NUMERIC(19,4) NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'disahkan', 'batal')),
  dibuat_oleh BIGINT,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  diubah_pada TIMESTAMPTZ,
  UNIQUE (no_dokumen)
);

CREATE TABLE saved_reports (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nama TEXT NOT NULL,
  laporan TEXT NOT NULL,
  params_json JSONB NOT NULL DEFAULT '{}'::jsonb,
  jadwal TEXT CHECK (jadwal IN ('harian', 'mingguan', 'bulanan')),
  aktif BOOLEAN NOT NULL DEFAULT TRUE,
  terakhir_jalan TIMESTAMPTZ,
  dibuat_oleh BIGINT,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  diubah_pada TIMESTAMPTZ
);

CREATE TABLE schema_migrations (
  file TEXT PRIMARY KEY,
  dijalankan_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  checksum TEXT NOT NULL
);

CREATE TABLE sessions (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  token TEXT NOT NULL,
  user_id BIGINT NOT NULL,
  perangkat TEXT,
  ip TEXT,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  terakhir_aktif TIMESTAMPTZ NOT NULL DEFAULT now(),
  kadaluarsa TEXT,
  diingat BOOLEAN NOT NULL DEFAULT FALSE,
  toko_kode TEXT,
  UNIQUE (token)
);

CREATE TABLE settings (
  kunci TEXT PRIMARY KEY,
  nilai TEXT,
  keterangan TEXT,
  diubah_pada TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE size_profile_sizes (
  profile_id BIGINT NOT NULL,
  size TEXT NOT NULL,
  jatah BIGINT NOT NULL DEFAULT 0 CHECK (jatah >= 0),
  urutan BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY (profile_id, size)
);

CREATE TABLE size_profiles (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  kode TEXT NOT NULL,
  nama TEXT NOT NULL,
  pasang_per_kodi BIGINT NOT NULL DEFAULT 20 CHECK (pasang_per_kodi > 0),
  kata_kunci TEXT NOT NULL DEFAULT '[]',
  bawaan BOOLEAN NOT NULL DEFAULT FALSE,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  diubah_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (kode)
);

CREATE TABLE stock_balances (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  product_id BIGINT NOT NULL,
  warehouse_id BIGINT NOT NULL,
  qty NUMERIC(19,4) NOT NULL DEFAULT 0,
  diubah_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (product_id, warehouse_id)
);

CREATE TABLE stock_ledger (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tanggal TIMESTAMPTZ NOT NULL DEFAULT now(),
  product_id BIGINT NOT NULL,
  warehouse_id BIGINT NOT NULL,
  location_id BIGINT,
  tipe_dokumen TEXT NOT NULL CHECK (tipe_dokumen IN ('pembelian', 'pembelian_batal', 'penjualan', 'retur', 'transfer', 'transfer_batal', 'opname', 'penyesuaian', 'saldo_awal')),
  dokumen_id BIGINT,
  qty_masuk NUMERIC(19,4) NOT NULL DEFAULT 0,
  qty_keluar NUMERIC(19,4) NOT NULL DEFAULT 0,
  saldo NUMERIC(19,4) NOT NULL DEFAULT 0,
  nilai_unit NUMERIC(19,4) NOT NULL DEFAULT 0,
  user_id BIGINT
);

CREATE TABLE stock_transfer_items (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  transfer_id BIGINT NOT NULL,
  product_id BIGINT NOT NULL,
  qty NUMERIC(19,4) NOT NULL CHECK (qty > 0),
  UNIQUE (transfer_id, product_id)
);

CREATE TABLE stock_transfers (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  no_dokumen TEXT NOT NULL,
  dari_warehouse BIGINT NOT NULL,
  ke_warehouse BIGINT NOT NULL,
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'disahkan', 'batal')),
  tanggal DATE NOT NULL DEFAULT CURRENT_DATE,
  dibuat_oleh BIGINT,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  diubah_pada TIMESTAMPTZ,
  dikirim_pada TIMESTAMPTZ,
  dikirim_oleh BIGINT,
  diterima_pada TIMESTAMPTZ,
  diterima_oleh BIGINT,
  UNIQUE (no_dokumen),
  CHECK (dari_warehouse <> ke_warehouse)
);

CREATE TABLE stores (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  kode TEXT NOT NULL,
  nama TEXT NOT NULL,
  alamat TEXT,
  telepon TEXT,
  email TEXT,
  logo TEXT,
  warehouse_id BIGINT,
  aktif BOOLEAN NOT NULL DEFAULT TRUE,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  diubah_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (kode)
);

CREATE TABLE struk_profil (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nama TEXT NOT NULL,
  bawaan BOOLEAN NOT NULL DEFAULT FALSE,
  kertas TEXT NOT NULL DEFAULT '80mm',
  lebar_mm NUMERIC(19,4),
  tinggi_mm NUMERIC(19,4),
  margin_atas NUMERIC(19,4) NOT NULL DEFAULT 3,
  margin_kanan NUMERIC(19,4) NOT NULL DEFAULT 2,
  margin_bawah NUMERIC(19,4) NOT NULL DEFAULT 3,
  margin_kiri NUMERIC(19,4) NOT NULL DEFAULT 2,
  ukuran_font NUMERIC(19,4) NOT NULL DEFAULT 11,
  blok JSONB NOT NULL DEFAULT '{}'::jsonb,
  teks JSONB NOT NULL DEFAULT '{}'::jsonb,
  dibuat_pada TIMESTAMPTZ NOT NULL,
  diubah_pada TIMESTAMPTZ
);

CREATE TABLE sub_stock_docs (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  no_dokumen TEXT NOT NULL,
  arah TEXT NOT NULL CHECK (arah IN ('masuk', 'keluar')),
  warehouse_id BIGINT NOT NULL,
  tanggal DATE NOT NULL DEFAULT CURRENT_DATE,
  alasan TEXT NOT NULL CHECK (alasan IN ( 'stok_awal', 'temuan', 'koreksi_pos', 'rusak', 'hilang', 'sampel', 'koreksi_neg', 'lainnya')),
  keterangan TEXT,
  status TEXT NOT NULL DEFAULT 'disahkan' CHECK (status IN ('disahkan', 'batal')),
  total_qty NUMERIC(19,4) NOT NULL DEFAULT 0,
  jumlah_item BIGINT NOT NULL DEFAULT 0,
  dibuat_oleh BIGINT,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  dibatalkan_pada TIMESTAMPTZ,
  batal_oleh BIGINT,
  alasan_batal TEXT,
  UNIQUE (no_dokumen),
  CHECK (
    (arah = 'masuk'  AND alasan IN ('stok_awal', 'temuan', 'koreksi_pos', 'lainnya'))
    OR
    (arah = 'keluar' AND alasan IN ('rusak', 'hilang', 'sampel', 'koreksi_neg', 'lainnya'))
  )
);

CREATE TABLE sub_stock_items (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  doc_id BIGINT NOT NULL,
  product_id BIGINT NOT NULL,
  qty NUMERIC(19,4) NOT NULL CHECK (qty > 0),
  satuan TEXT,
  stok_sebelum NUMERIC(19,4) NOT NULL DEFAULT 0,
  stok_sesudah NUMERIC(19,4) NOT NULL DEFAULT 0,
  UNIQUE (doc_id, product_id)
);

CREATE TABLE suppliers (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nama TEXT NOT NULL,
  telepon TEXT,
  alamat TEXT,
  termin_hari BIGINT NOT NULL DEFAULT 0,
  dibuat_oleh BIGINT,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  diubah_pada TIMESTAMPTZ,
  aktif BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE unit_conversions (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  product_id BIGINT NOT NULL,
  unit_id BIGINT NOT NULL,
  jumlah_per_satuan_dasar NUMERIC(19,4) NOT NULL CHECK (jumlah_per_satuan_dasar > 0),
  UNIQUE (product_id, unit_id)
);

CREATE TABLE units (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  kode TEXT NOT NULL,
  nama TEXT NOT NULL,
  dibuat_oleh BIGINT,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  diubah_pada TIMESTAMPTZ,
  UNIQUE (kode),
  UNIQUE (nama)
);

CREATE TABLE users (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nama TEXT NOT NULL,
  username TEXT NOT NULL,
  email TEXT,
  password_hash TEXT NOT NULL,
  role_id BIGINT NOT NULL,
  pin_supervisor_hash TEXT,
  aktif BOOLEAN NOT NULL DEFAULT TRUE,
  dibuat_oleh BIGINT,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  diubah_pada TIMESTAMPTZ,
  wa TEXT,
  cakupan_toko TEXT,
  wajib_ganti BOOLEAN NOT NULL DEFAULT FALSE,
  gagal BIGINT NOT NULL DEFAULT 0,
  kunci_sampai TIMESTAMPTZ,
  login_terakhir TEXT,
  sandi_diubah_pada TIMESTAMPTZ,
  toko_bawaan TEXT,
  mode_toko TEXT NOT NULL DEFAULT 'terbatas',
  periode_aktif BOOLEAN NOT NULL DEFAULT FALSE,
  jam_dari TEXT,
  jam_sampai TEXT,
  hari_aktif TEXT,
  zona TEXT NOT NULL DEFAULT 'Asia/Jakarta',
  login_shift BOOLEAN NOT NULL DEFAULT FALSE,
  maks_perangkat BIGINT NOT NULL DEFAULT 0,
  perlu_ditinjau BOOLEAN NOT NULL DEFAULT FALSE,
  toko_terakhir TEXT,
  device_id TEXT,
  UNIQUE (username)
);

CREATE TABLE warehouses (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  kode TEXT NOT NULL,
  nama TEXT NOT NULL,
  dibuat_oleh BIGINT,
  dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT now(),
  diubah_pada TIMESTAMPTZ,
  aktif BOOLEAN NOT NULL DEFAULT TRUE,
  UNIQUE (kode),
  UNIQUE (nama)
);

